input.newString:
import { getNotificationPreference } from './state'
import { toggleNotificationPreference } from './actions'

export default function Home() {
  const enabled = getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications: {enabled ? 'On' : 'Off'}</p>
      <form action={toggleNotificationPreference}>
        <button type="submit">Turn {enabled ? 'Off' : 'On'}</button>
      </form>
    </main>
  )
}

